package mcp

import (
	"context"
	"strings"
	"testing"

	mcplib "github.com/mark3labs/mcp-go/mcp"
	"github.com/mark3labs/mcp-go/server"
)

// TestRegisteredToolSurfaceHasUniqueNamesAndTypedSearch pins the combined
// MCP registration contract: the final server surface must expose unique
// tool names, and `search` must resolve to the typed in-process tool rather
// than the Cobra shell-out mirror. mcp-go stores tools by name, so the
// handler probe is load-bearing: if the walker leaks a shell-out `search`
// after the typed registration, it overwrites the typed handler and this
// test fails without spawning the companion CLI.
func TestRegisteredToolSurfaceHasUniqueNamesAndTypedSearch(t *testing.T) {
	t.Setenv("READWISE_CLI_PATH", "/definitely/not/readwise-pp-cli")

	s := server.NewMCPServer(
		"Readwise",
		"test",
		server.WithToolCapabilities(false),
	)
	RegisterTools(s)

	tools := s.ListTools()
	if len(tools) == 0 {
		t.Fatal("registered tool surface is empty")
	}

	seen := map[string]int{}
	for key, entry := range tools {
		if entry == nil {
			t.Fatalf("tool %q entry is nil", key)
		}
		if entry.Tool.Name == "" {
			t.Fatalf("tool registered under %q has empty Tool.Name", key)
		}
		if entry.Tool.Name != key {
			t.Fatalf("tool map key %q does not match Tool.Name %q", key, entry.Tool.Name)
		}
		seen[entry.Tool.Name]++
	}
	for name, count := range seen {
		if count != 1 {
			t.Fatalf("tool %q registered %d times, want once", name, count)
		}
	}

	searchTool, ok := tools["search"]
	if !ok {
		t.Fatal("search tool is missing from the registered MCP surface")
	}
	if seen["search"] != 1 {
		t.Fatalf("search registered %d times, want once", seen["search"])
	}
	if searchTool.Handler == nil {
		t.Fatal("search tool handler is nil")
	}

	result, err := searchTool.Handler(context.Background(), mcplib.CallToolRequest{
		Params: mcplib.CallToolParams{
			Name:      "search",
			Arguments: map[string]any{},
		},
	})
	if err != nil {
		t.Fatalf("search handler returned protocol error: %v", err)
	}
	text := mcpTextContent(t, result)
	if !result.IsError || !strings.Contains(text, "query is required") {
		t.Fatalf("search handler = isError %v text %q, want typed search validation error", result.IsError, text)
	}
	if strings.Contains(text, "companion CLI binary") || strings.Contains(text, "/definitely/not/readwise-pp-cli") {
		t.Fatalf("search handler was overwritten by shell-out mirror: %q", text)
	}

	listDescriptions := map[string]string{
		"book-tags_list":      "{results:[...Tag], count, returned_count, truncated}",
		"books_list":          "{results:[...Book], count, returned_count, truncated}",
		"documents_list":      "{results:[...Document], count, returned_count, truncated}",
		"highlight-tags_list": "{results:[...Tag], count, returned_count, truncated}",
		"highlights_list":     "{results:[...Highlight], count, returned_count, truncated}",
		"reader-tags_list":    "{results:[...ReaderTag], count, returned_count, truncated}",
	}
	for name, want := range listDescriptions {
		tool, ok := tools[name]
		if !ok {
			t.Fatalf("%s tool is missing from registered MCP surface", name)
		}
		if !strings.Contains(tool.Tool.Description, want) || strings.Contains(tool.Tool.Description, "Returns array of") {
			t.Fatalf("%s description = %q, want envelope shape %q", name, tool.Tool.Description, want)
		}
	}
	sqlTool, ok := tools["sql"]
	if !ok {
		t.Fatal("sql tool is missing from the registered MCP surface")
	}
	if !strings.Contains(sqlTool.Tool.Description, "Truncated results do not return a next_offset cursor") ||
		!strings.Contains(sqlTool.Tool.Description, "LIMIT/OFFSET") {
		t.Fatalf("sql description missing non-cursor paging guidance: %q", sqlTool.Tool.Description)
	}

	bulkUpdateTool, ok := tools["documents_bulk-update"]
	if !ok {
		t.Fatal("documents_bulk-update tool is missing from the registered MCP surface")
	}
	if bulkUpdateTool.Tool.Annotations.ReadOnlyHint == nil || *bulkUpdateTool.Tool.Annotations.ReadOnlyHint {
		t.Fatalf("documents_bulk-update readOnlyHint = %v, want false", bulkUpdateTool.Tool.Annotations.ReadOnlyHint)
	}
	if bulkUpdateTool.Tool.Annotations.DestructiveHint == nil || !*bulkUpdateTool.Tool.Annotations.DestructiveHint {
		t.Fatalf("documents_bulk-update destructiveHint = %v, want true", bulkUpdateTool.Tool.Annotations.DestructiveHint)
	}
}
